```python
import pulp

# Define the problem
problem = pulp.LpProblem("Fair_Allocation", pulp.LpMaximize)

# Define the decision variables
# x[i][j] = 1 if good i is allocated to person j, 0 otherwise
x = {}
for i in ["A", "B", "C"]:
    x[i] = {}
    for j in [1, 2, 3]:
        x[i][j] = pulp.LpVariable(f"x_{i}_{j}", 0, 1, pulp.LpInteger)

# Define the money allocation variables
# m[j] = amount of money allocated to person j
m = {}
for j in [1, 2, 3]:
    m[j] = pulp.LpVariable(f"m_{j}", 0, 5)

# Define the valuations
valuations = {
    1: {"A": 45, "B": 30, "C": 25},
    2: {"A": 35, "B": 40, "C": 25},
    3: {"A": 50, "B": 5, "C": 45},
}

# Objective function: Maximize the total social welfare
problem += pulp.lpSum(
    valuations[j][i] * x[i][j] + m[j] for i in ["A", "B", "C"] for j in [1, 2, 3]
)

# Constraints
# Each good can be allocated to at most one person
for i in ["A", "B", "C"]:
    problem += pulp.lpSum([x[i][j] for j in [1, 2, 3]]) <= 1

# Total money allocated cannot exceed 5 units
problem += pulp.lpSum([m[j] for j in [1, 2, 3]]) <= 5

# Solve the problem
problem.solve()

# Print the allocation
print("Allocation:")
for i in ["A", "B", "C"]:
    for j in [1, 2, 3]:
        if x[i][j].varValue == 1:
            print(f"Good {i} allocated to Person {j}")
for j in [1, 2, 3]:
    if m[j].varValue > 0:
        print(f"{m[j].varValue} units of money allocated to Person {j}")
```
