```python
import mip

# Create a MIP model
model = mip.Model()

# Decision variables:
# x_ij = 1 if Good i is allocated to Person j, 0 otherwise
# y_j = amount of money allocated to Person j
goods = ['A', 'B', 'C']
persons = [1, 2, 3]
x = {}
for i in goods:
    for j in persons:
        x[i, j] = model.add_var(var_type=mip.BINARY, name=f"x_{i}{j}")
y = {}
for j in persons:
    y[j] = model.add_var(var_type='C', name=f"y_{j}")

# Values of goods for each person
values = {
    (1, 'A'): 45, (1, 'B'): 30, (1, 'C'): 25,
    (2, 'A'): 35, (2, 'B'): 40, (2, 'C'): 25,
    (3, 'A'): 50, (3, 'B'): 5,  (3, 'C'): 45,
}

# Constraints:
# Each good is allocated to at most one person
for i in goods:
    model += mip.xsum(x[i, j] for j in persons) <= 1

# Total money allocated cannot exceed 5
model += mip.xsum(y[j] for j in persons) <= 5

# Objective function: Maximize total value
model.objective = mip.maximize(
    mip.xsum(values[j, i] * x[i, j] for i in goods for j in persons) +
    mip.xsum(y[j] for j in persons)
)

# Solve the model
model.optimize()

# Print the allocation
print("Allocation:")
for i in goods:
    for j in persons:
        if x[i, j].x > 0.5:
            print(f"Good {i} allocated to Person {j}")
for j in persons:
    if y[j].x > 0.5:
        print(f"Person {j} receives {y[j].x:.2f} units of money")
```

```python
import pulp

# Define the problem
problem = pulp.LpProblem("Fair_Allocation", pulp.LpMaximize)

# Define the decision variables
# x[i][j] = 1 if good i is allocated to person j, 0 otherwise
x = {}
for i in range(1, 4):
    x[i] = {}
    for j in range(1, 4):
        x[i][j] = pulp.LpVariable(f"x_{i}_{j}", 0, 1, pulp.LpInteger)

# Define the money allocation variables
# m[j] = amount of money allocated to person j
m = {}
for j in range(1, 4):
    m[j] = pulp.LpVariable(f"m_{j}", 0, 5)

# Define the valuations
valuations = {
    1: {1: 45, 2: 30, 3: 25},
    2: {1: 35, 2: 40, 3: 25},
    3: {1: 50, 2: 5, 3: 45},
}

# Objective function: maximize the total valuation
problem += pulp.lpSum(
    valuations[i][j] * x[i][j] + m[j]
    for i in range(1, 4)
    for j in range(1, 4)
)

# Constraints
# Each good can be allocated to at most one person
for i in range(1, 4):
    problem += pulp.lpSum(x[i][j] for j in range(1, 4)) <= 1

# Total money allocated cannot exceed 5
problem += pulp.lpSum(m[j] for j in range(1, 4)) <= 5

# Solve the problem
problem.solve()

# Print the allocation
print("Allocation:")
for i in range(1, 4):
    for j in range(1, 4):
        if x[i][j].value() == 1:
            print(f"Good {i} allocated to Person {j}")
for j in range(1, 4):
    if m[j].value() > 0:
        print(f"{m[j].value()} units of money allocated to Person {j}")

