```python
import pulp

# Define the problem
problem = pulp.LpProblem("Fair_Allocation", pulp.LpMaximize)

# Define the decision variables
# x[i][j] = 1 if good j is allocated to person i, 0 otherwise
x = {}
for i in range(1, 4):
    x[i] = {}
    for j in ["A", "B", "C"]:
        x[i][j] = pulp.LpVariable(f"x_{i}{j}", cat="Binary")

# Define the money allocation variables
m = {}
for i in range(1, 4):
    m[i] = pulp.LpVariable(f"m_{i}", lowBound=0, upBound=5)

# Define the valuations
valuations = {
    1: {"A": 45, "B": 30, "C": 25},
    2: {"A": 35, "B": 40, "C": 25},
    3: {"A": 50, "B": 5, "C": 45},
}

# Objective function: Maximize the total valuation
problem += pulp.lpSum(valuations[i][j] * x[i][j] + m[i] for i in range(1, 4) for j in ["A", "B", "C"])

# Constraints
# Each good can be allocated to at most one person
for j in ["A", "B", "C"]:
    problem += pulp.lpSum(x[i][j] for i in range(1, 4)) <= 1

# Total money allocated cannot exceed 5
problem += pulp.lpSum(m[i] for i in range(1, 4)) <= 5

# Solve the problem
problem.solve()

# Print the allocation
print("Allocation:")
for i in range(1, 4):
    print(f"Person {i}:")
    for j in ["A", "B", "C"]:
        if x[i][j].value() == 1:
            print(f"  Good {j}")
    print(f"  Money: {m[i].value()}")
```
